import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { User } from '../models';
import { v4 as uuidv4 } from 'uuid';

const LS_KEY = 'fos_user';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private _user$ = new BehaviorSubject<User | null>(this.loadUser());
  user$ = this._user$.asObservable();

  get token(): string | undefined {
    return this._user$.value?.token;
  }

  private loadUser(): User | null {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return null; }
  }

  private save(user: User | null) {
    if (user) localStorage.setItem(LS_KEY, JSON.stringify(user));
    else localStorage.removeItem(LS_KEY);
    this._user$.next(user);
  }

  login(username: string, password: string): Observable<User> {
    // Mock: accept any username/password, return token
    const user: User = {
      id: uuidv4(),
      username,
      name: username,
      token: 'mock-jwt-' + Math.random().toString(36).slice(2)
    };
    this.save(user);
    return of(user);
  }

  logout() {
    this.save(null);
  }

  isLoggedIn() {
    return !!this._user$.value;
  }
}
